// Validate & extract query params from webhook body
const body = $input.first().json.body ?? {};

// const platform  = body.platform  ?? null;
const domain = body.domain ?? null;
const name = body.name ?? null;
const competitor_id = body.competitor_id ?? null;

return [{ json: { domain, name, competitor_id } }];

